```typescript
import { DurableObject } from "cloudflare:workers";

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

const HOUR_MS = 60 * 60 * 1000;

export class ChatRoom extends DurableObject<Env> {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      this.ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS messages (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          author TEXT NOT NULL,
          body TEXT NOT NULL,
          created_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS state (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL
        );
      `);
      // One alarm per object: only schedule if none is pending.
      if ((await this.ctx.storage.getAlarm()) === null) {
        await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  // Methods are synchronous over SQL storage with no await between writes,
  // so each call runs to completion before the next one starts.
  postMessage(author: string, body: string): number {
    return this.ctx.storage.sql
      .exec<{ id: number }>(
        "INSERT INTO messages (author, body, created_at) VALUES (?, ?, ?) RETURNING id",
        author,
        body,
        Date.now(),
      )
      .one().id;
  }

  recentMessages(limit = 50) {
    return this.ctx.storage.sql
      .exec<{ id: number; author: string; body: string; created_at: number }>(
        "SELECT id, author, body, created_at FROM messages ORDER BY id DESC LIMIT ?",
        limit,
      )
      .toArray()
      .reverse();
  }

  setState(key: string, value: string): void {
    this.ctx.storage.sql.exec(
      "INSERT INTO state (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
      key,
      value,
    );
  }

  getState(key: string): string | null {
    const rows = this.ctx.storage.sql
      .exec<{ value: string }>("SELECT value FROM state WHERE key = ?", key)
      .toArray();
    return rows[0]?.value ?? null;
  }

  async alarm(): Promise<void> {
    // Hourly housekeeping: drop messages older than 7 days.
    this.ctx.storage.sql.exec(
      "DELETE FROM messages WHERE created_at < ?",
      Date.now() - 7 * 24 * HOUR_MS,
    );
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
  }
}
```

