import { DurableObject } from "cloudflare:workers";

export interface Env {
  CHAT_ROOM: DurableObjectNamespace<ChatRoom>;
}

const HOUR_MS = 60 * 60 * 1000;

export interface Message {
  id: number;
  author: string;
  body: string;
  createdAt: number;
}

export class ChatRoom extends DurableObject<Env> {
  constructor(ctx: DurableObjectState, env: Env) {
    super(ctx, env);
    ctx.blockConcurrencyWhile(async () => {
      this.ctx.storage.sql.exec(`
        CREATE TABLE IF NOT EXISTS messages (
          id INTEGER PRIMARY KEY AUTOINCREMENT,
          author TEXT NOT NULL,
          body TEXT NOT NULL,
          created_at INTEGER NOT NULL
        );
        CREATE TABLE IF NOT EXISTS state (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL
        );
      `);
      // Alarms are one per object. Only set one if none is pending.
      if ((await this.ctx.storage.getAlarm()) === null) {
        await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
      }
    });
  }

  // Writes are serialized by the object's single-threaded execution and input gates.
  // Each method does its related writes synchronously in one transaction, with no await between them.
  postMessage(author: string, body: string): Message {
    return this.ctx.storage.transactionSync(() => {
      const createdAt = Date.now();
      const { id } = this.ctx.storage.sql
        .exec<{ id: number }>(
          "INSERT INTO messages (author, body, created_at) VALUES (?, ?, ?) RETURNING id",
          author,
          body,
          createdAt,
        )
        .one();
      return { id, author, body, createdAt };
    });
  }

  setState(key: string, value: unknown): void {
    this.ctx.storage.sql.exec(
      "INSERT INTO state (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
      key,
      JSON.stringify(value),
    );
  }

  getState<T>(key: string): T | undefined {
    const rows = this.ctx.storage.sql
      .exec<{ value: string }>("SELECT value FROM state WHERE key = ?", key)
      .toArray();
    return rows.length ? (JSON.parse(rows[0].value) as T) : undefined;
  }

  recentMessages(limit = 50): Message[] {
    return this.ctx.storage.sql
      .exec<Message>(
        "SELECT id, author, body, created_at AS createdAt FROM messages ORDER BY id DESC LIMIT ?",
        limit,
      )
      .toArray()
      .reverse();
  }

  // Hourly wake-up. Reschedule first so a failure in the work below cannot stop the cycle.
  async alarm(): Promise<void> {
    await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);

    // Hourly work goes here. Example: drop messages older than 7 days.
    this.ctx.storage.sql.exec(
      "DELETE FROM messages WHERE created_at < ?",
      Date.now() - 7 * 24 * HOUR_MS,
    );
  }
}
