```ts
import { DurableObject } from "cloudflare:workers";

const HOUR_MS = 60 * 60 * 1000;
const STATE_KEY = "state";

export interface RoomState {
  messageCount: number;
  lastMessage: { author: string; body: string; at: number } | null;
  lastTickAt: number | null;
}

const emptyState = (): RoomState => ({
  messageCount: 0,
  lastMessage: null,
  lastTickAt: null,
});

export class ChatRoom extends DurableObject<Env> {
  // Each operation chains onto this tail, so a read-modify-write never
  // interleaves with another one across an await.
  private tail: Promise<unknown> = Promise.resolve();

  private serialize<T>(work: () => Promise<T>): Promise<T> {
    const run = this.tail.then(work);
    this.tail = run.catch(() => undefined);
    return run;
  }

  private async load(): Promise<RoomState> {
    return (await this.ctx.storage.get<RoomState>(STATE_KEY)) ?? emptyState();
  }

  private async ensureAlarm(): Promise<void> {
    if ((await this.ctx.storage.getAlarm()) === null) {
      await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
    }
  }

  async post(author: string, body: string): Promise<RoomState> {
    return this.serialize(async () => {
      const state = await this.load();
      state.messageCount += 1;
      state.lastMessage = { author, body, at: Date.now() };
      await this.ctx.storage.put(STATE_KEY, state);
      await this.ensureAlarm();
      return state;
    });
  }

  async read(): Promise<RoomState> {
    return this.serialize(() => this.load());
  }

  async alarm(): Promise<void> {
    try {
      await this.serialize(async () => {
        const state = await this.load();
        state.lastTickAt = Date.now();
        // Hourly work goes here.
        await this.ctx.storage.put(STATE_KEY, state);
      });
    } finally {
      await this.ctx.storage.setAlarm(Date.now() + HOUR_MS);
    }
  }
}
